import React, { useState, useEffect } from 'react';
import VideoInterviewPage from './components/video/VideoInterviewPage';

// Import Firebase auth
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth } from './firebase';

// Temporary placeholder components
const Header = ({ user, onLogout }) => (
  <div className="bg-white shadow p-4">
    <div className="flex justify-between items-center">
      <h1 className="text-2xl font-bold">AI Interview Platform</h1>
      {user && (
        <button onClick={onLogout} className="bg-red-500 text-white px-4 py-2 rounded">
          Logout
        </button>
      )}
    </div>
  </div>
);

const TabNavigation = ({ activeTab, setActiveTab }) => (
  <div className="bg-white shadow">
    <div className="flex gap-4 p-4">
      <button
        onClick={() => setActiveTab('interviewee')}
        className={`px-4 py-2 rounded ${activeTab === 'interviewee' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
      >
        Interviewee
      </button>
      <button
        onClick={() => setActiveTab('interviewer')}
        className={`px-4 py-2 rounded ${activeTab === 'interviewer' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
      >
        Interviewer
      </button>
    </div>
  </div>
);

const IntervieweeView = ({ onStartVideoInterview, uploadedFile, handleFileUpload, error, currentCandidate }) => (
  <div className="bg-white p-8 rounded-lg shadow">
    <h2 className="text-2xl font-bold mb-4">Upload Resume</h2>
    {error && <p className="text-red-500 mb-4">{error}</p>}
    <input
      type="file"
      onChange={handleFileUpload}
      accept=".pdf,.docx"
      className="mb-4 block w-full text-sm text-gray-500
        file:mr-4 file:py-2 file:px-4
        file:rounded-full file:border-0
        file:text-sm file:font-semibold
        file:bg-blue-50 file:text-blue-700
        hover:file:bg-blue-100"
    />
    {uploadedFile && <p className="mb-4 text-green-600">✅ Resume uploaded: {uploadedFile.name}</p>}
    {uploadedFile && currentCandidate && (
      <button
        onClick={onStartVideoInterview}
        className="bg-green-500 text-white px-6 py-3 rounded-lg hover:bg-green-600 transition"
      >
        🎥 Start Video Interview
      </button>
    )}
  </div>
);

const InterviewerDashboard = ({ candidates }) => (
  <div className="bg-white p-8 rounded-lg shadow">
    <h2 className="text-2xl font-bold mb-4">Candidates Dashboard</h2>
    {candidates.length === 0 ? (
      <p className="text-gray-500">No candidates yet. Complete an interview to see results here.</p>
    ) : (
      <div className="space-y-4">
        {candidates.map(c => (
          <div key={c.id} className="border border-gray-200 p-6 rounded-lg hover:shadow-lg transition">
            <div className="flex justify-between items-start mb-4">
              <div>
                <h3 className="text-xl font-bold text-gray-800">{c.name}</h3>
                <p className="text-gray-600">{c.email}</p>
                <p className="text-sm text-gray-500">{c.phone}</p>
              </div>
              <span className="bg-green-100 text-green-800 px-3 py-1 rounded-full text-sm font-semibold">
                Completed
              </span>
            </div>
            <div className="bg-gray-50 p-4 rounded-lg">
              <p className="font-semibold text-gray-700">{c.summary}</p>
              {c.answers && (
                <p className="text-sm text-gray-600 mt-2">
                  Questions Answered: {c.answers.length}
                </p>
              )}
            </div>
          </div>
        ))}
      </div>
    )}
  </div>
);

const WelcomeBackModal = ({ onResume, onStartFresh }) => (
  <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div className="bg-white p-8 rounded-lg shadow-xl max-w-md">
      <h2 className="text-2xl font-bold mb-4">Welcome Back!</h2>
      <p className="mb-6">You have an unfinished interview. Would you like to continue?</p>
      <div className="flex gap-4">
        <button onClick={onResume} className="bg-blue-500 text-white px-6 py-2 rounded hover:bg-blue-600 transition">
          Resume
        </button>
        <button onClick={onStartFresh} className="bg-gray-500 text-white px-6 py-2 rounded hover:bg-gray-600 transition">
          Start Fresh
        </button>
      </div>
    </div>
  </div>
);

const LandingPage = ({ onShowLogin, onShowSignup }) => (
  <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
    <div className="text-center">
      <h1 className="text-5xl font-bold mb-4 text-gray-800">AI Interview Platform</h1>
      <p className="text-xl text-gray-600 mb-8">Conduct smart video interviews with AI</p>
      <div className="flex gap-4 justify-center">
        <button onClick={onShowLogin} className="bg-blue-500 text-white px-8 py-3 rounded-lg text-lg hover:bg-blue-600 transition">
          Login
        </button>
        <button onClick={onShowSignup} className="bg-green-500 text-white px-8 py-3 rounded-lg text-lg hover:bg-green-600 transition">
          Sign Up
        </button>
      </div>
    </div>
  </div>
);

const LoginPage = ({ onBack, onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onLogin({ uid: '123', email, name: email.split('@')[0] });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
      <div className="bg-white p-8 rounded-lg shadow-xl max-w-md w-full">
        <h2 className="text-3xl font-bold mb-6">Login</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full p-3 border rounded mb-4"
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full p-3 border rounded mb-4"
            required
          />
          <button type="submit" className="w-full bg-blue-500 text-white p-3 rounded hover:bg-blue-600 transition">
            Login
          </button>
        </form>
        <button onClick={onBack} className="w-full mt-4 text-gray-600 hover:text-gray-800">
          Back
        </button>
      </div>
    </div>
  );
};

const SignupPage = ({ onBack, onSignup }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onSignup({ uid: '123', email, name: email.split('@')[0] });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
      <div className="bg-white p-8 rounded-lg shadow-xl max-w-md w-full">
        <h2 className="text-3xl font-bold mb-6">Sign Up</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full p-3 border rounded mb-4"
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full p-3 border rounded mb-4"
            required
          />
          <button type="submit" className="w-full bg-green-500 text-white p-3 rounded hover:bg-green-600 transition">
            Sign Up
          </button>
        </form>
        <button onClick={onBack} className="w-full mt-4 text-gray-600 hover:text-gray-800">
          Back
        </button>
      </div>
    </div>
  );
};

function App() {
  const [showVideoInterview, setShowVideoInterview] = useState(false);
  const [authView, setAuthView] = useState('landing');
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('interviewee');
  const [candidates, setCandidates] = useState([]);
  const [currentCandidate, setCurrentCandidate] = useState(null);
  const [uploadedFile, setUploadedFile] = useState(null);
  const [showWelcomeBack, setShowWelcomeBack] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
      if (firebaseUser) {
        const userData = {
          uid: firebaseUser.uid,
          email: firebaseUser.email,
          name: firebaseUser.displayName || firebaseUser.email.split('@')[0],
          photoURL: firebaseUser.photoURL
        };
        setUser(userData);
        setAuthView('authenticated');
      } else {
        setUser(null);
        setAuthView('landing');
      }
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    setAuthView('authenticated');
  };

  const handleSignup = (userData) => {
    setUser(userData);
    setAuthView('authenticated');
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setUser(null);
      setAuthView('landing');
      setCandidates([]);
      setCurrentCandidate(null);
      setShowVideoInterview(false);
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const fileType = file.name.split('.').pop().toLowerCase();
    if (!['pdf', 'docx'].includes(fileType)) {
      setError('Please upload a PDF or DOCX file');
      return;
    }

    setError('');
    setUploadedFile(file);

    const newCandidate = {
      id: `candidate-${Date.now()}`,
      name: user?.name || 'Candidate',
      email: user?.email || 'email@example.com',
      phone: '+1234567890',
      answers: [],
      completed: false,
      startedAt: Date.now()
    };

    setCurrentCandidate(newCandidate);
  };

  const handleStartVideoInterview = () => {
    if (!uploadedFile || !currentCandidate) {
      setError('Please upload your resume first!');
      return;
    }
    setShowVideoInterview(true);
  };

  const handleVideoInterviewComplete = (completedCandidate) => {
    setCandidates(prev => [...prev, completedCandidate]);
    setShowVideoInterview(false);
    setCurrentCandidate(null);
    setUploadedFile(null);
    setActiveTab('interviewer');
    alert('🎉 Interview completed! Check the Interviewer tab to see results.');
  };

  const handleVideoInterviewBack = () => {
    if (window.confirm('Are you sure you want to exit? Progress will be lost.')) {
      setShowVideoInterview(false);
    }
  };

  const handleWelcomeBack = (resume) => {
    setShowWelcomeBack(false);
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600 font-medium">Loading...</p>
        </div>
      </div>
    );
  }

  if (authView === 'landing') {
    return <LandingPage onShowLogin={() => setAuthView('login')} onShowSignup={() => setAuthView('signup')} />;
  }

  if (authView === 'login') {
    return <LoginPage onBack={() => setAuthView('landing')} onLogin={handleLogin} />;
  }

  if (authView === 'signup') {
    return <SignupPage onBack={() => setAuthView('landing')} onSignup={handleSignup} />;
  }

  if (showVideoInterview) {
    return (
      <VideoInterviewPage
        candidate={currentCandidate}
        onComplete={handleVideoInterviewComplete}
        onBack={handleVideoInterviewBack}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {showWelcomeBack && (
        <WelcomeBackModal
          onResume={() => handleWelcomeBack(true)}
          onStartFresh={() => handleWelcomeBack(false)}
        />
      )}

      <Header user={user} onLogout={handleLogout} />
      <TabNavigation activeTab={activeTab} setActiveTab={setActiveTab} />

      <div className="max-w-7xl mx-auto px-6 pb-8">
        {activeTab === 'interviewee' ? (
          <IntervieweeView
            handleFileUpload={handleFileUpload}
            uploadedFile={uploadedFile}
            error={error}
            currentCandidate={currentCandidate}
            onStartVideoInterview={handleStartVideoInterview}
          />
        ) : (
          <InterviewerDashboard candidates={candidates} />
        )}
      </div>
    </div>
  );
}

export default App;
